     1→//! Provides the `ObservedBlobSidecars` struct which allows for rejecting `BlobSidecar`s
     2→//! that we have already seen over the gossip network.
     3→//! Only `BlobSidecar`s that have completed proposer signature verification can be added
     4→//! to this cache to reduce DoS risks.
     5→
     6→use crate::observed_block_producers::ProposalKey;
     7→use std::collections::{HashMap, HashSet};
     8→use std::marker::PhantomData;
     9→use std::sync::Arc;
    10→use types::{BlobSidecar, ChainSpec, DataColumnSidecar, EthSpec, Slot};
    11→
    12→#[derive(Debug, PartialEq)]
    13→pub enum Error {
    14→    /// The slot of the provided `ObservableDataSidecar` is prior to finalization and should not have been provided
    15→    /// to this function. This is an internal error.
    16→    FinalizedDataSidecar { slot: Slot, finalized_slot: Slot },
    17→    /// The data sidecar contains an invalid index, the data sidecar is invalid.
    18→    /// Note: The invalid data should have been caught and flagged as an error much before reaching
    19→    /// here.
    20→    InvalidDataIndex(u64),
    21→}
    22→
    23→pub trait ObservableDataSidecar {
    24→    fn slot(&self) -> Slot;
    25→    fn block_proposer_index(&self) -> u64;
    26→    fn index(&self) -> u64;
    27→    fn max_num_of_items(spec: &ChainSpec, slot: Slot) -> usize;
    28→}
    29→
    30→impl<E: EthSpec> ObservableDataSidecar for BlobSidecar<E> {
    31→    fn slot(&self) -> Slot {
    32→        self.slot()
    33→    }
    34→
    35→    fn block_proposer_index(&self) -> u64 {
    36→        self.block_proposer_index()
    37→    }
    38→
    39→    fn index(&self) -> u64 {
    40→        self.index
    41→    }
    42→
    43→    fn max_num_of_items(spec: &ChainSpec, slot: Slot) -> usize {
    44→        spec.max_blobs_per_block(slot.epoch(E::slots_per_epoch())) as usize
    45→    }
    46→}
    47→
    48→impl<E: EthSpec> ObservableDataSidecar for DataColumnSidecar<E> {
    49→    fn slot(&self) -> Slot {
    50→        self.slot()
    51→    }
    52→
    53→    fn block_proposer_index(&self) -> u64 {
    54→        self.block_proposer_index()
    55→    }
    56→
    57→    fn index(&self) -> u64 {
    58→        self.index
    59→    }
    60→
    61→    fn max_num_of_items(_spec: &ChainSpec, _slot: Slot) -> usize {
    62→        E::number_of_columns()
    63→    }
    64→}
    65→
    66→/// Maintains a cache of seen `ObservableDataSidecar`s that are received over gossip
    67→/// and have been gossip verified.
    68→///
    69→/// The cache supports pruning based upon the finalized epoch. It does not automatically prune, you
    70→/// must call `Self::prune` manually.
    71→///
    72→/// Note: To prevent DoS attacks, this cache must include only items that have received some DoS resistance
    73→/// like checking the proposer signature.
    74→pub struct ObservedDataSidecars<T: ObservableDataSidecar> {
    75→    finalized_slot: Slot,
    76→    /// Stores all received data indices for a given `(ValidatorIndex, Slot)` tuple.
    77→    items: HashMap<ProposalKey, HashSet<u64>>,
    78→    spec: Arc<ChainSpec>,
    79→    _phantom: PhantomData<T>,
    80→}
    81→
    82→impl<T: ObservableDataSidecar> ObservedDataSidecars<T> {
    83→    /// Instantiates `Self` with `finalized_slot == 0`.
    84→    pub fn new(spec: Arc<ChainSpec>) -> Self {
    85→        Self {
    86→            finalized_slot: Slot::new(0),
    87→            items: HashMap::new(),
    88→            spec,
    89→            _phantom: PhantomData,
    90→        }
    91→    }
    92→
    93→    /// Observe the `data_sidecar` at (`data_sidecar.block_proposer_index, data_sidecar.slot`).
    94→    /// This will update `self` so future calls to it indicate that this `data_sidecar` is known.
    95→    ///
    96→    /// The supplied `data_sidecar` **MUST** have completed proposer signature verification.
    97→    pub fn observe_sidecar(&mut self, data_sidecar: &T) -> Result<bool, Error> {
    98→        self.sanitize_data_sidecar(data_sidecar)?;
    99→
   100→        let data_indices = self
   101→            .items
   102→            .entry(ProposalKey {
   103→                slot: data_sidecar.slot(),
   104→                proposer: data_sidecar.block_proposer_index(),
   105→            })
   106→            .or_insert_with(|| {
   107→                HashSet::with_capacity(T::max_num_of_items(&self.spec, data_sidecar.slot()))
   108→            });
   109→        let did_not_exist = data_indices.insert(data_sidecar.index());
   110→
   111→        Ok(!did_not_exist)
   112→    }
   113→
   114→    /// Returns `true` if the `data_sidecar` has already been observed in the cache within the prune window.
   115→    pub fn proposer_is_known(&self, data_sidecar: &T) -> Result<bool, Error> {
   116→        self.sanitize_data_sidecar(data_sidecar)?;
   117→        let is_known = self
   118→            .items
   119→            .get(&ProposalKey {
   120→                slot: data_sidecar.slot(),
   121→                proposer: data_sidecar.block_proposer_index(),
   122→            })
   123→            .is_some_and(|indices| indices.contains(&data_sidecar.index()));
   124→        Ok(is_known)
   125→    }
   126→
   127→    pub fn known_for_proposal(&self, proposal_key: &ProposalKey) -> Option<&HashSet<u64>> {
   128→        self.items.get(proposal_key)
   129→    }
   130→
   131→    fn sanitize_data_sidecar(&self, data_sidecar: &T) -> Result<(), Error> {
   132→        if data_sidecar.index() >= T::max_num_of_items(&self.spec, data_sidecar.slot()) as u64 {
   133→            return Err(Error::InvalidDataIndex(data_sidecar.index()));
   134→        }
   135→        let finalized_slot = self.finalized_slot;
   136→        if finalized_slot > 0 && data_sidecar.slot() <= finalized_slot {
   137→            return Err(Error::FinalizedDataSidecar {
   138→                slot: data_sidecar.slot(),
   139→                finalized_slot,
   140→            });
   141→        }
   142→
   143→        Ok(())
   144→    }
   145→
   146→    /// Prune `data_sidecar` observations for slots less than or equal to the given slot.
   147→    pub fn prune(&mut self, finalized_slot: Slot) {
   148→        if finalized_slot == 0 {
   149→            return;
   150→        }
   151→
   152→        self.finalized_slot = finalized_slot;
   153→        self.items.retain(|k, _| k.slot > finalized_slot);
   154→    }
   155→}
   156→
   157→/// Abstraction to control "observation" of gossip messages (currently just blobs and data columns).
   158→///
   159→/// If a type returns `false` for `observe` then the message will not be immediately added to its
   160→/// respective gossip observation cache. Unobserved messages should usually be observed later.
   161→pub trait ObservationStrategy {
   162→    fn observe() -> bool;
   163→}
   164→
   165→/// Type for messages that are observed immediately.
   166→pub struct Observe;
   167→/// Type for messages that have not been observed.
   168→#[derive(Debug)]
   169→pub struct DoNotObserve;
   170→
   171→impl ObservationStrategy for Observe {
   172→    fn observe() -> bool {
   173→        true
   174→    }
   175→}
   176→
   177→impl ObservationStrategy for DoNotObserve {
   178→    fn observe() -> bool {
   179→        false
   180→    }
   181→}
   182→
   183→#[cfg(test)]
   184→mod tests {
   185→    use super::*;
   186→    use crate::test_utils::test_spec;
   187→    use bls::Hash256;
   188→    use std::sync::Arc;
   189→    use types::{Epoch, MainnetEthSpec};
   190→
   191→    type E = MainnetEthSpec;
   192→
   193→    fn get_blob_sidecar(slot: u64, proposer_index: u64, index: u64) -> Arc<BlobSidecar<E>> {
   194→        let mut blob_sidecar = BlobSidecar::empty();
   195→        blob_sidecar.signed_block_header.message.slot = slot.into();
   196→        blob_sidecar.signed_block_header.message.proposer_index = proposer_index;
   197→        blob_sidecar.index = index;
   198→        Arc::new(blob_sidecar)
   199→    }
   200→
   201→    #[test]
   202→    fn pruning() {
   203→        let spec = Arc::new(test_spec::<E>());
