async fn check_rpc_custody_columns_availability_and_import(
    self: &Arc<Self>,
    slot: Slot,
    block_root: Hash256,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    self.check_columns_for_slashability(
        block_root,
        custody_columns.iter().map(|c| c.as_ref()),
    )?;

    // This slot value is purely informative for the consumers of
    // `AvailabilityProcessingStatus::MissingComponents` to log an error with a slot.
    let availability = self.data_availability_checker.put_rpc_custody_columns(
        block_root,
        slot,
        custody_columns,
    )?;

    self.process_availability(slot, availability, || Ok(()))
        .await
}

fn check_columns_for_slashability<'a>(
    self: &Arc<Self>,
    block_root: Hash256,
    custody_columns: impl IntoIterator<Item = &'a DataColumnSidecar<T::EthSpec>>,
) -> Result<(), BlockError> {
    let mut slashable_cache = self.observed_slashable.write();
    // Process all unique block headers - previous logic assumed all headers were identical and

/// Put a list of custody columns received via RPC into the availability cache. This performs KZG
/// verification on the blobs in the list.
#[allow(clippy::type_complexity)]
#[instrument(skip_all, level = "trace")]
pub fn put_rpc_custody_columns(
    &self,
    block_root: Hash256,
    slot: Slot,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
) -> Result<Availability<T::EthSpec>, AvailabilityCheckError> {
    // Attributes fault to the specific peer that sent an invalid column
    let kzg_verified_columns =
        KzgVerifiedDataColumn::from_batch_with_scoring(custody_columns, &self.kzg)
            .map_err(AvailabilityCheckError::InvalidColumn)?;

    // Filter out columns that aren't required for custody for this slot
    // This is required because `data_columns_by_root` requests the **latest** CGC that _may_
    // not be yet effective for data availability check, as CGC changes are only effecive from
    // a new epoch.
    let epoch = slot.epoch(T::EthSpec::slots_per_epoch());
    let sampling_columns = self
        .custody_context
        .sampling_columns_for_epoch(epoch, &self.spec);
    let verified_custody_columns = kzg_verified_columns
        .into_iter()
        .filter(|col| sampling_columns.contains(&col.index()))
        .map(KzgVerifiedCustodyDataColumn::from_asserted_custody)
        .collect::<Vec<_>>();

    self.availability_cache
        .put_kzg_verified_data_columns(block_root, verified_custody_columns)
}

